187: function drawMenuMinimap(last) {
188:   const canvas = dom.menuMinimap;
189:   const ctx = canvas.getContext('2d');
190:   const w = canvas.width, h = canvas.height;
191:   ctx.clearRect(0, 0, w, h);
192:   ctx.fillStyle = 'rgba(5,7,10,.4)';
193:   ctx.fillRect(0, 0, w, h);
194: 
195:   // faint grid
196:   ctx.strokeStyle = 'rgba(255,255,255,.035)';
197:   ctx.lineWidth = 1;
198:   for (let x = 20; x < w; x += 42) {
199:     ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, h); ctx.stroke();
200:   }
201:   for (let y = 16; y < h; y += 42) {
202:     ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke();
203:   }
204: 
205:   if (!last) {
206:     ctx.save();
207:     ctx.translate(w / 2, h / 2);
208:     ctx.setLineDash([4, 10]);
209:     ctx.strokeStyle = 'rgba(255,77,31,.28)';
210:     ctx.lineWidth = 1.5;
211:     ctx.beginPath();
212:     ctx.ellipse(0, 0, w * 0.33, h * 0.27, -0.18, 0, TAU);
213:     ctx.stroke();
214:     ctx.setLineDash([]);
215:     ctx.strokeStyle = 'rgba(255,255,255,.08)';
216:     ctx.beginPath(); ctx.moveTo(-9, 0); ctx.lineTo(9, 0); ctx.moveTo(0, -9); ctx.lineTo(0, 9); ctx.stroke();
217:     ctx.restore();
218:     return;
219:   }
220: 
221:   const preview = analyzePreview(last.points, { targetLength: 1900 });
222:   if (!preview.prepared.length) return;
223:   let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
224:   for (const p of preview.prepared) {
225:     minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x);
226:     minY = Math.min(minY, p.y); maxY = Math.max(maxY, p.y);
227:   }
228:   const pad = 30;
229:   const scale = Math.min((w - pad * 2) / (maxX - minX || 1), (h - pad * 2) / (maxY - minY || 1));
230:   const ox = (w - (maxX - minX) * scale) / 2 - minX * scale;
231:   const oy = (h - (maxY - minY) * scale) / 2 - minY * scale;
232:   const map = (p) => ({ x: p.x * scale + ox, y: p.y * scale + oy });
233: 
234:   ctx.save();
235:   ctx.lineJoin = 'round';
236:   ctx.lineCap = 'round';
237:   ctx.beginPath();
238:   preview.prepared.forEach((p, i) => {
239:     const q = map(p);
240:     if (i === 0) ctx.moveTo(q.x, q.y); else ctx.lineTo(q.x, q.y);
241:   });
242:   ctx.closePath();
243:   ctx.strokeStyle = 'rgba(255,77,31,.16)';
244:   ctx.lineWidth = 13;
245:   ctx.shadowColor = 'rgba(255,77,31,.7)';
246:   ctx.shadowBlur = 18;
247:   ctx.stroke();
248:   ctx.shadowBlur = 0;
249:   ctx.strokeStyle = 'rgba(7,9,12,.9)';
250:   ctx.lineWidth = 7;
251:   ctx.stroke();
252:   ctx.strokeStyle = '#f3efe5';
253:   ctx.lineWidth = 2.4;
254:   ctx.stroke();
255: 
256:   // start marker
257:   const start = map(preview.prepared[0]);
258:   ctx.fillStyle = '#ff4d1f';
259:   ctx.beginPath();
260:   ctx.arc(start.x, start.y, 3.5, 0, TAU);
261:   ctx.fill();
262:   ctx.strokeStyle = 'rgba(255,77,31,.8)';
263:   ctx.lineWidth = 1;
264:   ctx.beginPath();
265:   ctx.arc(start.x, start.y, 8, 0, TAU);
266:   ctx.stroke();
267:   ctx.restore();
268: }
