421: async function beginBuild(rawPoints, { instant = false } = {}) {
422:   if (building) return;
423:   building = true;
424:   audio.ensure();
425:   audio.click(520);
426:   const trackData = createTrackData(rawPoints, { targetLength: 1900, halfWidth: 7.2 });
427:   if (!trackData.valid) {
428:     building = false;
429:     toast('That circuit could not be paved. Try a cleaner loop.');
430:     return;
431:   }
432:   const saved = {
433:     points: rawPoints.map((p) => ({ x: p.x, y: p.y })),
434:     name: trackData.name,
435:     seed: trackData.seed,
436:     length: Math.round(trackData.length),
437:     turns: trackData.turns,
438:     difficulty: diffLevel
