import { createRequire } from 'node:module';
import { join } from 'node:path';
import { readFileSync } from 'node:fs';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const browser = await chromium.launch({
  headless: false, executablePath: '/opt/google/chrome/chrome',
  args: ['--enable-gpu', '--ignore-gpu-blocklist', '--enable-unsafe-webgpu', '--use-angle=vulkan',
    '--enable-features=Vulkan', '--use-vulkan=swiftshader', '--use-webgpu-adapter=swiftshader', '--disable-vulkan-surface']
});
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://localhost:3002/?demo=race&go=1&track=0', { waitUntil: 'load' });
await page.waitForFunction(() => window.__apex && document.querySelector('#loading')?.style.display === 'none');
const result = await page.evaluate(() => {
  const apex = window.__apex;
  apex.startRaceNow();
  const race = apex.race;
  const tr = race.track;
  let frames = 0;
  const snaps = [];
  while (race.state === 'racing' && frames < 60 * 220) {
    const p = race.player;
    const near = race.locator.nearest(p.pos.x, p.pos.z);
    const look = tr.samples[(near.index + 26) % tr.N];
    const desiredYaw = Math.atan2(look.x - p.pos.x, look.z - p.pos.z);
    let diff = desiredYaw - p.yaw;
    while (diff > Math.PI) diff -= Math.PI * 2;
    while (diff < -Math.PI) diff += Math.PI * 2;
    apex.setDemoInput({ left: diff > 0.025, right: diff < -0.025 });
    apex.tick(1 / 60);
    frames++;
    if (frames % (60 * 15) === 0) {
      snaps.push({ t: Math.round(race.time), lb: document.getElementById('leaderboard-rows')?.innerText.replace(/\n/g, ' | ') });
    }
  }
  apex.setDemoInput({ left: false, right: false });
  return {
    frames, state: race.state, time: Math.round(race.time),
    playerLaps: race.player.lapsCompleted, playerFinished: race.player.finished,
    ai: race.ai.map((a) => ({ name: a.name, dist: Math.round(a.dist), fin: a.finished, ft: a.finishTime && Math.round(a.finishTime) })),
    snaps,
    resultsShown: race.resultsShown,
    resultsText: document.getElementById('results-rows')?.innerText.replace(/\n/g, ' | ')
  };
});
console.log(JSON.stringify(result, null, 2));
console.log('errors', errors.slice(0, 8));
await browser.close();

