  for (let i = 0; i < m; i++) {
    const a = pts[i];
    const b = pts[(i + 1) % m];
    const axMin = Math.min(a.x, b.x), axMax = Math.max(a.x, b.x);
    const ayMin = Math.min(a.y, b.y), ayMax = Math.max(a.y, b.y);
    for (let j = i + 2; j < m; j++) {
      if (i === 0 && j === m - 1) continue;
      if (j - i < 2) continue;
      const c = pts[j];
