function buildPolygonVertices(rng) {
  // A real circuit is not a rounded pentagon. Build a star-shaped ring with
  // a deliberate mix of long straights, fast sweepers and tight technical
  // clusters. Vertices stay ordered by angle, so the base loop cannot cross
  // itself; the fillet pass turns it into straights and arcs.
  const n = 9 + Math.floor(rng() * 7);
  const gaps = [];
  for (let i = 0; i < n; i++) gaps.push(0.45 + rng() * 1.15);

  // One or two long main straights.
  const longCount = 1 + Math.floor(rng() * 2);
  for (let k = 0; k < longCount; k++) {
    gaps[Math.floor(rng() * n)] *= 1.5 + rng() * 0.85;
  }

  // Two or three technical clusters: closely spaced corners that become
  // esses, chicanes or a hairpin once filleted.
  const complex = new Uint8Array(n);
  const clusterCount = 2 + Math.floor(rng() * 2);
  for (let c = 0; c < clusterCount; c++) {
    const start = Math.floor(rng() * n);
    const len = 2 + Math.floor(rng() * 2);
    for (let k = 0; k < len; k++) {
      const idx = (start + k) % n;
      gaps[idx] *= 0.52 + rng() * 0.2;
      complex[idx] = 1;
    }
  }

  const gapSum = gaps.reduce((a, b) => a + b, 0);
  const stretchX = 0.9 + rng() * 0.3;
  const stretchY = 0.9 + rng() * 0.3;
  let angle = rng() * TAU;
  const verts = [];
  for (let i = 0; i < n; i++) {
    angle += (gaps[i] / gapSum) * TAU;
    let radius = 1 + (rng() * 2 - 1) * 0.3;
    if (complex[i]) {
      // Alternate in and out so clusters form S-bends rather than blobs.
      radius += (i % 2 === 0 ? -1 : 1) * (0.1 + rng() * 0.14);
    }
    radius = Math.max(0.52, radius);
    verts.push({
      x: Math.cos(angle) * radius * stretchX,
      y: Math.sin(angle) * radius * stretchY
    });
  }
  return verts;
}

function filletPolygon(verts, rng) {
  const n = verts.length;
  const corners = [];
  for (let i = 0; i < n; i++) {
    const a = verts[(i - 1 + n) % n];
    const b = verts[i];
    const c = verts[(i + 1) % n];
    const uBA = vUnit(vSub(a, b));
    const uBC = vUnit(vSub(c, b));
    const interior = Math.acos(clamp(uBA.x * uBC.x + uBA.y * uBC.y, -1, 1));
    const edge = Math.min(vDist(a, b), vDist(b, c));
    // Tight corners need enough tangent to make a real hairpin; fast
    // sweepers need only a little so the main straight stays long.
    let frac;
    if (interior < 1.15) frac = 0.15 + rng() * 0.15;
    else if (interior > 2.05) frac = 0.055 + rng() * 0.075;
    else frac = 0.09 + rng() * 0.11;
    const tangent = Math.min(edge * frac, edge * 0.38);
    const radius = tangent * Math.tan(interior / 2);
    const bisector = vUnit({ x: uBA.x + uBC.x, y: uBA.y + uBC.y });
    const offset = radius / Math.sin(interior / 2);
    const center = { x: b.x + bisector.x * offset, y: b.y + bisector.y * offset };
    const p = { x: b.x + uBA.x * tangent, y: b.y + uBA.y * tangent };
    const q = { x: b.x + uBC.x * tangent, y: b.y + uBC.y * tangent };
    const aP = Math.atan2(p.y - center.y, p.x - center.x);
    const aQ = Math.atan2(q.y - center.y, q.x - center.x);
    let sweep = aQ - aP;
    while (sweep > Math.PI) sweep -= TAU;
    while (sweep < -Math.PI) sweep += TAU;
    corners.push({ p, q, center, radius, aP, sweep });
  }

