    const N = 120;
    const pts = [];
    for (let i = 0; i < N; i++) {
      const q = p.getPointAtLength((i / N) * len);
      pts.push({ x: q.x, y: q.y });
    }
    p.remove();
    // normalize to 0..1
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
