  const out = [];
  const a = resample(BASE[0].points, 80);
  const b = resample(BASE[1].points, 80);
  for (let i = 0; i < count; i++) {
    const rng = rngFactory(12345 + i * 999);
    const w = 0.25 + rng() * 0.5;
    const mirror = rng() > 0.5 ? -1 : 1;
    const sx = 0.92 + rng() * 0.16;
    const sy = 0.92 + rng() * 0.16;
    const pts = [];
    for (let j = 0; j < a.length; j++) {
      let x = a[j][0] * (1 - w) + b[j][0] * w;
      let y = a[j][1] * (1 - w) + b[j][1] * w;
      x += (rng() - 0.5) * 0.012;
      y += (rng() - 0.5) * 0.012;
      x = 0.5 + (x - 0.5) * sx * mirror;
      y = 0.5 + (y - 0.5) * sy;
      pts.push([x, y]);
    }
    out.push({ name: `VARIANT ${i + 1}`, points: pts });
  }
  return out;
