function buildPolygonVertices(rng) {
  // A real circuit is not a rounded pentagon. Build a star-shaped ring with
  // a deliberate mix of long straights, fast sweepers and tight technical
  // clusters. Vertices stay ordered by angle, so the base loop cannot cross
  // itself; the fillet pass turns it into straights and arcs.
  const n = 16 + Math.floor(rng() * 7);
  const gaps = [];
  for (let i = 0; i < n; i++) gaps.push(0.45 + rng() * 0.75);

  // One or two long main straights.
  const longCount = 1 + Math.floor(rng() * 2);
  for (let k = 0; k < longCount; k++) {
    gaps[Math.floor(rng() * n)] *= 1.35 + rng() * 0.5;
  }

  // Two or three technical clusters: closely spaced corners that become
  // esses, chicanes or a hairpin once filleted.
  const complex = new Uint8Array(n);
  const clusterCount = 2 + Math.floor(rng() * 2);
  for (let c = 0; c < clusterCount; c++) {
    const start = Math.floor(rng() * n);
    const len = 2 + Math.floor(rng() * 2);
    for (let k = 0; k < len; k++) {
      const idx = (start + k) % n;
      gaps[idx] *= 0.78 + rng() * 0.16;
      complex[idx] = 1;
    }
  }

  const gapSum = gaps.reduce((a, b) => a + b, 0);
  const stretchX = 0.9 + rng() * 0.3;
  const stretchY = 0.9 + rng() * 0.3;
  let angle = rng() * TAU;
  const verts = [];
  for (let i = 0; i < n; i++) {
    angle += (gaps[i] / gapSum) * TAU;
    let radius = 1 + (rng() * 2 - 1) * 0.22;
    if (complex[i]) {
      // Alternate in and out so clusters form S-bends rather than blobs.
      radius += (i % 2 === 0 ? -1 : 1) * (0.07 + rng() * 0.09);
    }
    radius = Math.max(0.58, radius);
    verts.push({
      x: Math.cos(angle) * radius * stretchX,
      y: Math.sin(angle) * radius * stretchY
    });
  }
  return verts;
}

input.newString:
function buildPolygonVertices(rng) {
  // Real circuits are built from a handful of recognisable ingredients:
  // a long main straight, one or more hairpins, a set of esses, fast
  // sweepers and the odd chicane. Build those features explicitly, then lay
  // them out around a ring. Vertices keep increasing polar angle, so the
  // base loop can never cross itself; the fillet pass turns the corners
  // into straights and arcs. The radius of each feature is offset from a
  // gently varying ring, which keeps the result a circuit rather than a
  // wobbly circle.
  const features = [];

  // Main straight.
  features.push({
    kind: 'straight',
    weight: 0.8 + rng() * 0.5,
    nodes: [{ t: 0, r: 0 }, { t: 1, r: 0 }]
  });

  // Hairpins: a narrow out-and-back loop. arm is the length of the two
  // parallel arms, tip is how far the apex sits beyond them. A negative
  // direction folds the loop into the infield instead.
  const hairpinCount = 1 + Math.floor(rng() * 3);
  for (let h = 0; h < hairpinCount; h++) {
    const dir = rng() < 0.6 ? 1 : -1;
    const arm = dir * (0.2 + rng() * 0.24);
    const tip = dir * (0.08 + rng() * 0.14);
    features.push({
      kind: 'hairpin',
      weight: 0.16 + rng() * 0.14,
      nodes: [
        { t: 0, r: 0 },
        { t: 0.13, r: arm },
        { t: 0.5, r: arm + tip },
        { t: 0.87, r: arm },
        { t: 1, r: 0 }
      ]
    });
  }

  // Esses: a run of quick direction changes. Alternating radius offsets
  // read as left-right-left once the corners are filleted.
  const esseCount = 1 + Math.floor(rng() * 2);
  for (let e = 0; e < esseCount; e++) {
    const count = 3 + Math.floor(rng() * 3);
    const amp = 0.07 + rng() * 0.09;
    const nodes = [{ t: 0, r: 0 }];
    for (let i = 0; i < count; i++) {
      nodes.push({
        t: (i + 1) / (count + 1),
        r: (i % 2 === 0 ? amp : -amp) * (0.8 + rng() * 0.45)
      });
    }
    nodes.push({ t: 1, r: 0 });
    features.push({ kind: 'esse', weight: 0.26 + rng() * 0.3, nodes });
  }

  // Fast sweepers.
  const sweeperCount = 1 + Math.floor(rng() * 2);
  for (let s = 0; s < sweeperCount; s++) {
    const amp = 0.1 + rng() * 0.18;
    features.push({
      kind: 'sweeper',
      weight: 0.36 + rng() * 0.32,
      nodes: [
        { t: 0, r: 0 },
        { t: 0.55, r: amp * (0.55 + rng() * 0.45) },
        { t: 1, r: amp }
      ]
    });
  }

  // Occasional chicane.
  if (rng() < 0.6) {
    const amp = 0.08 + rng() * 0.1;
    features.push({
      kind: 'chicane',
      weight: 0.18 + rng() * 0.14,
      nodes: [
        { t: 0, r: 0 },
        { t: 0.3, r: amp },
        { t: 0.65, r: -amp },
        { t: 1, r: 0 }
      ]
    });
  }

  // Shuffle the order so every circuit starts its lap somewhere different.
  for (let i = features.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [features[i], features[j]] = [features[j], features[i]];
  }

  // Reserve part of the circle for connectors between features. Those
  // connectors are the long straights that make a lap breathe.
  const connectorBudget = TAU * (0.38 + rng() * 0.12);
  const weightSum = features.reduce((sum, f) => sum + f.weight, 0);
  const connectorWeights = features.map(() => 0.35 + rng() * 0.85);
  const connectorSum = connectorWeights.reduce((a, b) => a + b, 0);

  const stretchX = 0.88 + rng() * 0.3;
  const stretchY = 0.88 + rng() * 0.3;
  const phase1 = rng() * TAU;
  const phase2 = rng() * TAU;
  const phase3 = rng() * TAU;
  let angle = rng() * TAU;

  const verts = [];
  features.forEach((feature, fi) => {
    let prevT = 0;
    feature.nodes.forEach((node, ni) => {
      let gap;
      if (ni === 0) {
        gap = (connectorWeights[fi] / connectorSum) * connectorBudget;
      } else {
        gap = ((node.t - prevT) * feature.weight / weightSum) * (TAU - connectorBudget);
        prevT = node.t;
      }
      angle += gap;
      const base = 1
        + 0.13 * Math.sin(2 * angle + phase1)
        + 0.08 * Math.sin(3 * angle + phase2)
        + 0.04 * Math.sin(5 * angle + phase3);
      const radius = Math.max(0.32, base + node.r);
      verts.push({
        x: Math.cos(angle) * radius * stretchX,
        y: Math.sin(angle) * radius * stretchY
      });
    });
  });
  return verts;
}

