import { createRequire } from 'node:module';
import { join } from 'node:path';
import { readFileSync } from 'node:fs';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const BASE = [
  {
    name: 'VELVET',
    points: [
      [0.50, 0.90], [0.60, 0.86], [0.70, 0.77], [0.76, 0.64], [0.73, 0.52],
      [0.79, 0.43], [0.90, 0.36], [0.91, 0.25], [0.83, 0.18], [0.70, 0.19],
      [0.60, 0.14], [0.47, 0.15], [0.34, 0.12], [0.21, 0.15], [0.12, 0.23],
      [0.10, 0.35], [0.18, 0.42], [0.13, 0.52], [0.08, 0.65], [0.13, 0.76],
      [0.26, 0.81], [0.37, 0.86]
    ]
  },
  {
    name: 'IRON',
    points: [
      [0.48, 0.88], [0.62, 0.84], [0.70, 0.72], [0.69, 0.58], [0.62, 0.47],
      [0.68, 0.36], [0.82, 0.33], [0.90, 0.24], [0.86, 0.15], [0.72, 0.12],
      [0.58, 0.18], [0.47, 0.12], [0.33, 0.14], [0.22, 0.23], [0.24, 0.35],
      [0.34, 0.42], [0.30, 0.54], [0.18, 0.58], [0.10, 0.68], [0.13, 0.81],
      [0.26, 0.87], [0.37, 0.84]
    ]
  }
];

function rngFactory(seed) {
  let a = seed >>> 0;
  return () => {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function warpTrack(basePoints, rng) {
  const mirror = rng() < 0.5 ? -1 : 1;
  const rot = rng() * Math.PI * 2;
  const sx = 0.9 + rng() * 0.2;
  const sy = 0.9 + rng() * 0.2;
  const a1 = (rng() * 2 - 1) * 0.055;
  const a2 = (rng() * 2 - 1) * 0.03;
  const b1 = (rng() * 2 - 1) * 0.055;
  const b2 = (rng() * 2 - 1) * 0.03;
  const f1 = 1 + Math.floor(rng() * 2);
  const f2 = 2 + Math.floor(rng() * 2);
  const p1 = rng() * Math.PI * 2;
  const p2 = rng() * Math.PI * 2;
  const p3 = rng() * Math.PI * 2;
  const p4 = rng() * Math.PI * 2;
  const cos = Math.cos(rot), sin = Math.sin(rot);
  return basePoints.map(([x, y]) => {
    let px = (x - 0.5) * mirror * sx;
    let py = (y - 0.5) * sy;
    const wx = a1 * Math.sin(Math.PI * 2 * f1 * py + p1) + a2 * Math.sin(Math.PI * 2 * f2 * px + p2);
    const wy = b1 * Math.sin(Math.PI * 2 * f1 * px + p3) + b2 * Math.sin(Math.PI * 2 * f2 * py + p4);
    px += wx;
    py += wy;
    const rx = px * cos - py * sin;
    const ry = px * sin + py * cos;
    return [0.5 + rx, 0.5 + ry];
  });
}

const VARIANTS = [];
for (let i = 0; i < 9; i++) {
  const rng = rngFactory(98765 + i * 7919);
  const base = BASE[i % BASE.length];
  VARIANTS.push({ name: `${base.name} ${i + 1}`, points: warpTrack(base.points, rng) });
}

const browser = await chromium.launch({
  headless: false, executablePath: '/opt/google/chrome/chrome',
  args: ['--enable-gpu', '--ignore-gpu-blocklist', '--enable-unsafe-webgpu', '--use-angle=vulkan',
    '--enable-features=Vulkan', '--use-vulkan=swiftshader', '--use-webgpu-adapter=swiftshader', '--disable-vulkan-surface']
});
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
await page.goto('http://localhost:3002/?demo=draw', { waitUntil: 'load' });
await page.waitForFunction(() => window.__apex && window.__apex.state === 'draw');
await page.waitForTimeout(800);

const tracks = await page.evaluate((templates) => {
  const ds = window.__apex.drawScreen;
  return templates.map((t) => {
    const pts = t.points.map(([x, y]) => ({ x: 60 + x * 800, y: 40 + y * 480 }));
    ds._loadInspiration(pts, t.name);
    ds.exampleProgress = 1;
    ds.finishExample();
    return { name: t.name, points: pts, turns: ds.analyzed.turns, straight: ds.analyzed.longestStraight, radius: ds.analyzed.minRadius, valid: ds.analyzed.valid, intersects: ds.analyzed.selfIntersects };
  });
}, VARIANTS);

await page.evaluate((tracks) => {
  const cell = 420;
  const c = document.createElement('canvas');
  c.width = cell * 3;
  c.height = cell * 3;
  c.id = 'montage';
  c.style.cssText = 'position:fixed;left:0;top:0;z-index:99999;background:#070a0e;width:1260px;height:1260px';
  document.body.appendChild(c);
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#070a0e';
  ctx.fillRect(0, 0, c.width, c.height);
  tracks.forEach((t, i) => {
    const ox = (i % 3) * cell;
    const oy = Math.floor(i / 3) * cell;
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    for (const p of t.points) { minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x); minY = Math.min(minY, p.y); maxY = Math.max(maxY, p.y); }
    const pad = 34;
    const s = Math.min((cell - pad * 2) / (maxX - minX || 1), (cell - pad * 2) / (maxY - minY || 1));
    const map = (p) => ({ x: ox + pad + (p.x - minX) * s, y: oy + pad + (p.y - minY) * s });
    ctx.strokeStyle = '#f3efe5';
    ctx.lineWidth = 3;
    ctx.lineJoin = 'round';
    ctx.beginPath();
    t.points.forEach((p, j) => { const q = map(p); if (j === 0) ctx.moveTo(q.x, q.y); else ctx.lineTo(q.x, q.y); });
    ctx.closePath();
    ctx.stroke();
    ctx.fillStyle = '#ff4d1f';
    ctx.font = '15px monospace';
    ctx.fillText(t.name, ox + 14, oy + 24);
    ctx.fillStyle = t.valid && !t.intersects ? '#8a8d93' : '#ff5b5b';
    ctx.font = '12px monospace';
    ctx.fillText(`${t.turns}t · ${t.straight}m · R${t.radius}${t.intersects ? ' · CROSS' : ''}`, ox + 14, oy + 42);
  });
}, tracks);
await page.waitForTimeout(300);
