import { createRequire } from 'node:module';
import { join } from 'node:path';
import { readFileSync, readdirSync, writeFileSync } from 'node:fs';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const dir = '/tmp/opencode/circuits';
const files = readdirSync(dir).filter((f) => f.endsWith('.svg'));
const svgs = files.map((f) => ({ name: f.replace('.svg', ''), text: readFileSync(join(dir, f), 'utf8') }));

const browser = await chromium.launch({
  headless: false, executablePath: '/opt/google/chrome/chrome',
  args: ['--enable-gpu', '--ignore-gpu-blocklist', '--enable-unsafe-webgpu', '--use-angle=vulkan',
    '--enable-features=Vulkan', '--use-vulkan=swiftshader', '--use-webgpu-adapter=swiftshader', '--disable-vulkan-surface']
});
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
await page.goto('http://localhost:3002/?demo=draw', { waitUntil: 'load' });
await page.waitForFunction(() => window.__apex && window.__apex.state === 'draw');
await page.waitForTimeout(500);

const result = await page.evaluate((items) => {
  const N = 192;
  const holder = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  holder.style.cssText = 'position:fixed;left:-9999px;top:0;width:1px;height:1px';
  document.body.appendChild(holder);
  const out = [];
  for (const item of items) {
    try {
      const doc = new DOMParser().parseFromString(item.text, 'image/svg+xml');
      const paths = [...doc.querySelectorAll('path')];
      if (!paths.length) { out.push({ name: item.name, error: 'no path' }); continue; }
      let best = null;
      for (const p of paths) {
        const el = document.createElementNS('http://www.w3.org/2000/svg', 'path');
        el.setAttribute('d', p.getAttribute('d'));
        holder.appendChild(el);
        const len = el.getTotalLength();
        if (!best || len > best.len) { if (best) best.el.remove(); best = { el, len }; }
        else el.remove();
      }
      if (!best || best.len < 10) { out.push({ name: item.name, error: 'short' }); continue; }
      const pts = [];
      for (let i = 0; i < N; i++) {
        const q = best.el.getPointAtLength((i / N) * best.len);
        pts.push([q.x, q.y]);
      }
      best.el.remove();
      let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
      for (const [x, y] of pts) {
        minX = Math.min(minX, x); maxX = Math.max(maxX, x);
        minY = Math.min(minY, y); maxY = Math.max(maxY, y);
      }
      const scale = 1 / Math.max(maxX - minX, maxY - minY);
      const ox = (1 - (maxX - minX) * scale) / 2;
      const oy = (1 - (maxY - minY) * scale) / 2;
      out.push({
        name: item.name,
        points: pts.map(([x, y]) => [
          +(ox + (x - minX) * scale).toFixed(4),
          +(oy + (y - minY) * scale).toFixed(4)
        ])
      });
    } catch (e) {
      out.push({ name: item.name, error: String(e) });
    }
  }
  holder.remove();
  return out;
}, svgs);

const ok = result.filter((r) => r.points);
const bad = result.filter((r) => r.error);
console.log('OK:', ok.map((r) => r.name).join(', '));
console.log('BAD:', bad.map((r) => `${r.name} (${r.error})`).join(', '));
writeFileSync('/tmp/opencode/circuits-extracted.json', JSON.stringify(ok, null, 0));
await browser.close();

