await page.goto('http://localhost:3002/?demo=draw', { waitUntil: 'load' });
await page.waitForTimeout(500);

await page.evaluate((tracks) => {
  const cols = 4;
  const cell = 320;
  const rows = Math.ceil(tracks.length / cols);
  const c = document.createElement('canvas');
  c.width = cell * cols;
  c.height = cell * rows;
  c.id = 'montage';
  c.style.cssText = `position:fixed;left:0;top:0;z-index:99999;background:#070a0e;width:${cell * cols}px;height:${cell * rows}px`;
  document.body.appendChild(c);
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#070a0e';
  ctx.fillRect(0, 0, c.width, c.height);
  tracks.forEach((t, i) => {
    const ox = (i % cols) * cell;
    const oy = Math.floor(i / cols) * cell;
    const pad = 26;
    const s = Math.min((cell - pad * 2) / 1, (cell - pad * 2) / 1);
    ctx.strokeStyle = '#f3efe5';
    ctx.lineWidth = 2.5;
    ctx.lineJoin = 'round';
    ctx.beginPath();
    t.points.forEach(([x, y], j) => {
      const px = ox + pad + x * s;
      const py = oy + pad + y * s;
      if (j === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
    });
    ctx.closePath();
    ctx.stroke();
    ctx.fillStyle = '#ff4d1f';
    ctx.font = '13px monospace';
    ctx.fillText(t.name, ox + 12, oy + 20);
  });
}, tracks);
await page.waitForTimeout(300);
const el = await page.$('#montage');
await el.screenshot({ path: '/tmp/opencode/shots/real-tracks.jpg', type: 'jpeg', quality: 85 });
await browser.close();

