process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const tracks = JSON.parse(readFileSync('/tmp/opencode/circuits-extracted.json', 'utf8'));
const TAU = Math.PI * 2;

function rngFactory(seed) {
  let a = seed >>> 0;
  return () => {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function mutate(basePoints, rng) {
  const n = basePoints.length;
  const cx = 0.5, cy = 0.5;
  const mirror = rng() < 0.5 ? -1 : 1;
  const rot = rng() * TAU;
  const sx = 0.9 + rng() * 0.2;
  const sy = 0.9 + rng() * 0.2;
  const ax = (rng() * 2 - 1) * 0.026;
  const bx = (rng() * 2 - 1) * 0.014;
  const ay = (rng() * 2 - 1) * 0.026;
  const by = (rng() * 2 - 1) * 0.014;
  const f1 = 1 + Math.floor(rng() * 2);
  const f2 = 2 + Math.floor(rng() * 2);
  const p1 = rng() * TAU, p2 = rng() * TAU, p3 = rng() * TAU, p4 = rng() * TAU;

  // Arc length parameter for localized bumps.
  const seg = [];
  let total = 0;
  for (let i = 0; i < n; i++) {
    const a = basePoints[i];
    const b = basePoints[(i + 1) % n];
    const len = Math.hypot(b[0] - a[0], b[1] - a[1]);
    seg.push(len);
    total += len;
  }
  const s = [];
  let acc = 0;
  for (let i = 0; i < n; i++) { s.push(acc / total); acc += seg[i]; }

  // 1-3 smooth local warps along the normal.
  const bumps = [];
  const bumpCount = 1 + Math.floor(rng() * 3);
  for (let k = 0; k < bumpCount; k++) {
    bumps.push({
      center: rng(),
      width: 0.035 + rng() * 0.07,
      amp: (rng() * 2 - 1) * (0.025 + rng() * 0.035)
