import { createRequire } from 'node:module';
import { join } from 'node:path';
import { readFileSync } from 'node:fs';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const all = JSON.parse(readFileSync('/tmp/opencode/circuits-extracted.json', 'utf8'));
const TAU = Math.PI * 2;

function rngFactory(seed) {
  let a = seed >>> 0;
  return () => {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function resampleClosed(points, count) {
  const n = points.length;
  const seg = [];
  let total = 0;
  for (let i = 0; i < n; i++) {
    const a = points[i], b = points[(i + 1) % n];
    const len = Math.hypot(b[0] - a[0], b[1] - a[1]);
    seg.push(len); total += len;
  }
  const out = [];
  let idx = 0, acc = 0;
  const step = total / count;
  for (let i = 0; i < count; i++) {
    const target = i * step;
    while (idx < n - 1 && acc + seg[idx] < target) { acc += seg[idx]; idx++; }
    const t = seg[idx] ? (target - acc) / seg[idx] : 0;
    const a = points[idx], b = points[(idx + 1) % n];
    out.push([a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t]);
  }
  return out;
}

function mutate(basePoints, rng, strength = 1) {
  const n = basePoints.length;
  const mirror = rng() < 0.5 ? -1 : 1;
  const rot = rng() * TAU;
  const sx = 0.93 + rng() * 0.14;
  const sy = 0.93 + rng() * 0.14;
  const ax = (rng() * 2 - 1) * 0.014 * strength;
  const bx = (rng() * 2 - 1) * 0.007 * strength;
  const ay = (rng() * 2 - 1) * 0.014 * strength;
  const by = (rng() * 2 - 1) * 0.007 * strength;
  const f1 = 1 + Math.floor(rng() * 2);
  const f2 = 2 + Math.floor(rng() * 2);
  const p1 = rng() * TAU, p2 = rng() * TAU, p3 = rng() * TAU, p4 = rng() * TAU;

  const seg = [];
  let total = 0;
  for (let i = 0; i < n; i++) {
    const a = basePoints[i], b = basePoints[(i + 1) % n];
    const len = Math.hypot(b[0] - a[0], b[1] - a[1]);
    seg.push(len); total += len;
  }
  const s = [];
  let acc = 0;
  for (let i = 0; i < n; i++) { s.push(acc / total); acc += seg[i]; }

  const bumps = [];
  const bumpCount = 1 + Math.floor(rng() * 3);
  for (let k = 0; k < bumpCount; k++) {
    bumps.push({
      center: rng(),
      width: 0.05 + rng() * 0.06,
      amp: (rng() * 2 - 1) * (0.009 + rng() * 0.018) * strength
    });
  }

  const cos = Math.cos(rot), sin = Math.sin(rot);
  return basePoints.map(([x, y], i) => {
    let px = (x - 0.5) * mirror * sx;
    let py = (y - 0.5) * sy;
    px += ax * Math.sin(TAU * f1 * py + p1) + bx * Math.sin(TAU * f2 * px + p2);
    py += ay * Math.sin(TAU * f1 * px + p3) + by * Math.sin(TAU * f2 * py + p4);
    const prev = basePoints[(i - 1 + n) % n];
    const next = basePoints[(i + 1) % n];
    const tx = next[0] - prev[0], ty = next[1] - prev[1];
    const tl = Math.hypot(tx, ty) || 1;
    let offset = 0;
    for (const b of bumps) {
      let d = Math.abs(s[i] - b.center);
      d = Math.min(d, 1 - d);
      offset += b.amp * Math.exp(-(d * d) / (2 * b.width * b.width));
    }
    px += (-ty / tl) * offset;
    py += (tx / tl) * offset;
    const rx = px * cos - py * sin;
    const ry = px * sin + py * cos;
    return [0.5 + rx, 0.5 + ry];
  });
}

