    const oy = Math.floor(i / cols) * cell;
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    for (const p of t.points) { minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x); minY = Math.min(minY, p.y); maxY = Math.max(maxY, p.y); }
    const pad = 24;
    const s = Math.min((cell - pad * 2) / (maxX - minX || 1), (cell - pad * 2) / (maxY - minY || 1));
    const map = (p) => ({ x: ox + pad + (p.x - minX) * s, y: oy + pad + (p.y - minY) * s });
    ctx.strokeStyle = '#f3efe5';
    ctx.lineWidth = 2.5;
    ctx.lineJoin = 'round';
    ctx.beginPath();
    t.points.forEach((p, j) => { const q = map(p); if (j === 0) ctx.moveTo(q.x, q.y); else ctx.lineTo(q.x, q.y); });
    ctx.closePath();
    ctx.stroke();
    ctx.fillStyle = '#ff4d1f';
    ctx.font = '11px monospace';
    ctx.fillText(t.name, ox + 10, oy + 17);
    ctx.fillStyle = t.valid && !t.intersects ? '#8a8d93' : '#ff5b5b';
    ctx.font = '10px monospace';
    ctx.fillText(`${t.turns}t · ${t.straight}m · R${t.radius}${t.intersects ? ' · CROSS' : ''}`, ox + 10, oy + 31);
  });
}, results);
await page.waitForTimeout(300);
const el = await page.$('#montage');
await el.screenshot({ path: '/tmp/opencode/shots/all-templates.jpg', type: 'jpeg', quality: 85 });
console.log(JSON.stringify(results.map((t) => `${t.name} | ${t.turns}t ${t.straight}m R${t.radius} ${t.valid ? 'VALID' : 'INVALID'}${t.intersects ? ' CROSS' : ''}`), null, 1));
await browser.close();

