import { createRequire } from 'node:module';
import { join } from 'node:path';
import { readFileSync } from 'node:fs';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const browser = await chromium.launch({
  headless: false, executablePath: '/opt/google/chrome/chrome',
  args: ['--enable-gpu', '--ignore-gpu-blocklist', '--enable-unsafe-webgpu', '--use-angle=vulkan',
    '--enable-features=Vulkan', '--use-vulkan=swiftshader', '--use-webgpu-adapter=swiftshader', '--disable-vulkan-surface']
});
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`));
page.on('console', (m) => { if (m.type() === 'error') errors.push(`console: ${m.text()}`); });
page.on('response', (r) => { if (r.status() >= 400 && r.url().startsWith('http://localhost:3002')) errors.push(`HTTP ${r.status()} ${r.url()}`); });

await page.goto('http://localhost:3002/?demo=draw', { waitUntil: 'load' });
await page.waitForFunction(() => window.__apex && window.__apex.state === 'draw');
await page.waitForTimeout(1800);

const previews = [];
for (let i = 0; i < 3; i++) {
  await page.click('#btn-example');
  await page.waitForTimeout(1900);
  const info = await page.evaluate(() => {
    const ds = window.__apex.drawScreen;
    return {
      label: ds.exampleLabel || '',
      points: ds.examplePoints ? ds.examplePoints.length : 0,
      analyzed: ds.analyzed ? {
        turns: ds.analyzed.turns,
        straight: ds.analyzed.longestStraight,
        radius: ds.analyzed.minRadius,
        valid: ds.analyzed.valid,
        intersects: ds.analyzed.selfIntersects
      } : null
    };
  });
  previews.push(info);
  await page.screenshot({ path: `/tmp/opencode/shots/draw-${i + 1}.jpg`, type: 'jpeg', quality: 85 });
}

// Build the last preview and race.
await page.click('#btn-build');
await page.waitForFunction(() => window.__apex.race && window.__apex.race.state === 'countdown', null, { timeout: 15000 });
await page.evaluate(() => window.__apex.startRaceNow());
await page.waitForTimeout(3000);
await page.screenshot({ path: '/tmp/opencode/shots/race.jpg', type: 'jpeg', quality: 85 });
const raceInfo = await page.evaluate(() => {
  const r = window.__apex.race;
  return {
    state: r.state,
    track: r.track && r.track.name,
    turns: r.track && r.track.turns,
    length: r.track && r.track.length,
    speed: r.player && r.player.speed,
    position: r.player && r.player.position
  };
});

console.log(JSON.stringify({ previews, raceInfo, errors }, null, 2));
await browser.close();

