import { createRequire } from 'node:module';
import { join } from 'node:path';
import { readFileSync } from 'node:fs';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const browser = await chromium.launch({
  headless: false, executablePath: '/opt/google/chrome/chrome',
  args: ['--enable-gpu', '--ignore-gpu-blocklist', '--enable-unsafe-webgpu', '--use-angle=vulkan',
    '--enable-features=Vulkan', '--use-vulkan=swiftshader', '--use-webgpu-adapter=swiftshader', '--disable-vulkan-surface']
});
const page = await browser.newPage({ viewport: { width: 900, height: 700 } });
const errors = [];
page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`));
page.on('console', (m) => { if (m.type() === 'error') errors.push(`console: ${m.text()}`); });
await page.goto('http://localhost:3002/?demo=draw', { waitUntil: 'load' });
await page.waitForFunction(() => window.__apex && window.__apex.state === 'draw');
await page.waitForTimeout(600);

const result = await page.evaluate(async () => {
  const { audio } = await import('/src/audio.js');
  const SR = 44100;
  const DUR = 8;
  const off = new OfflineAudioContext(1, SR * DUR, SR);

  // Build the same master bus `ensure()` normally creates.
  audio.ctx = off;
  audio.master = off.createGain();
  audio.master.gain.value = 0.55;
  const comp = off.createDynamicsCompressor();
  comp.threshold.value = -14;
  comp.ratio.value = 4;
  audio.master.connect(comp);
  comp.connect(off.destination);
  audio.running = false;
  audio.startRace();

  const phase = (t) => {
    if (t < 0.7) return { speed: 0, throttle: 0, brake: 0, slip: 0 };
    if (t < 4.2) {
      const k = (t - 0.7) / 3.5;
      return { speed: 95 * Math.pow(k, 0.72), throttle: 1, brake: 0, slip: 0 };
    }
    if (t < 5.2) {
      const k = (t - 4.2);
      return { speed: Math.max(18, 95 - k * 77), throttle: 0, brake: 1, slip: 0.15 };
    }
    if (t < 6.4) {
      return { speed: Math.max(10, 18 - (t - 5.2) * 6), throttle: 0.15, brake: 0, slip: 0.05 };
    }
    return { speed: 45, throttle: 0.7, brake: 0, slip: 0 };
  };

  const fps = 30;
  for (let i = 1; i < DUR * fps; i++) {
    const when = i / fps;
    off.suspend(when).then(() => {
      audio.update({ ...phase(when), offroad: false, running: true });
      off.resume();
    });
  }

  const buffer = await off.startRendering();
  const data = buffer.getChannelData(0);

  const rmsAt = (a, b) => {
    let sum = 0;
    const i0 = Math.floor(a * SR), i1 = Math.floor(b * SR);
    for (let i = i0; i < i1; i++) sum += data[i] * data[i];
    return Math.sqrt(sum / Math.max(1, i1 - i0));
  };
  const peakAt = (a, b) => {
    let p = 0;
    for (let i = Math.floor(a * SR); i < Math.floor(b * SR); i++) p = Math.max(p, Math.abs(data[i]));
    return p;
  };
  const zcrAt = (a, b) => {
    let c = 0;
    for (let i = Math.floor(a * SR) + 1; i < Math.floor(b * SR); i++) {
      if ((data[i - 1] < 0) !== (data[i] < 0)) c++;
    }
    return c / (b - a);
  };

  // Naive DFT magnitude on a window around full throttle (3.0s) and on idle.
  const spectrum = (center) => {
    const N = 2048;
    const start = Math.floor(center * SR) - N / 2;
    const win = new Float32Array(N);
    for (let i = 0; i < N; i++) {
      win[i] = data[start + i] * (0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (N - 1)));
    }
    const bands = [];
    for (const target of [200, 300, 400, 500, 600, 700, 800, 1000, 1250, 1500, 2000, 2500, 3000, 4000, 5000, 6000]) {
      let re = 0, im = 0;
      for (let i = 0; i < N; i++) {
        const ang = (2 * Math.PI * target * i) / SR;
        re += win[i] * Math.cos(ang);
        im -= win[i] * Math.sin(ang);
      }
      bands.push({ hz: target, mag: +Math.hypot(re, im).toFixed(3) });
    }
    return bands;
  };

  audio.stopRace();
  return {
    rms: {
      idle: +rmsAt(0.15, 0.65).toFixed(4),
      accel: +rmsAt(1.0, 3.9).toFixed(4),
      braking: +rmsAt(4.4, 5.1).toFixed(4),
      overrun: +rmsAt(5.5, 6.3).toFixed(4)
    },
    peaks: {
      idle: +peakAt(0.15, 0.65).toFixed(3),
      accel: +peakAt(1.0, 3.9).toFixed(3)
    },
    zcr: { idle: +zcrAt(0.2, 0.6).toFixed(0), accel: +zcrAt(3.0, 3.4).toFixed(0) },
    spectrumAccel: spectrum(3.0),
    spectrumIdle: spectrum(0.3),
    sampleRate: buffer.sampleRate,
    ctxStateBeforeStop: audio.running
  };
});

console.log(JSON.stringify({ result, errors }, null, 2));
await browser.close();

