import { createRequire } from 'node:module';
import { join } from 'node:path';
import { readFileSync } from 'node:fs';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const browser = await chromium.launch({
  headless: false, executablePath: '/opt/google/chrome/chrome',
  args: ['--enable-gpu', '--ignore-gpu-blocklist', '--enable-unsafe-webgpu', '--use-angle=vulkan',
    '--enable-features=Vulkan', '--use-vulkan=swiftshader', '--use-webgpu-adapter=swiftshader',
    '--disable-vulkan-surface', '--autoplay-policy=no-user-gesture-required']
});

const errors = [];
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`));
page.on('console', (m) => { if (m.type() === 'error') errors.push(`console: ${m.text()}`); });
page.on('response', (r) => { if (r.status() >= 400 && r.url().startsWith('http://localhost:3002')) errors.push(`HTTP ${r.status()} ${r.url()}`); });

await page.goto('http://localhost:3002/?demo=race&go=1', { waitUntil: 'load' });
await page.waitForFunction(() => window.__apex && window.__apex.race && window.__apex.race.state === 'racing', null, { timeout: 20000 });
await page.waitForTimeout(3500);

const info = await page.evaluate(async () => {
  const { audio } = await import('/src/audio.js');
  const r = window.__apex.race;
  const tower = document.getElementById('timing-tower');
  const towerRows = tower ? [...tower.querySelectorAll('.tower-row')] : [];
  return {
    raceState: r.state,
    track: r.track.name,
    turns: r.track.turns,
    length: r.track.length,
    speedKmh: +(Math.abs(r.player.vLong) * 3.6).toFixed(0),
    position: r.player.position,
    gear: document.getElementById('hud-gear')?.textContent,
    towerVisible: tower ? getComputedStyle(tower).display !== 'none' : false,
    towerRows: towerRows.length,
    towerText: tower ? tower.textContent.replace(/\s+/g, ' ').trim().slice(0, 160) : '',
    audio: {
      ctxState: audio.ctx?.state,
      running: audio.running,
      muted: audio.muted,
      nativeRate: audio.ctx?.sampleRate,
      fundamental: audio.oscA ? +audio.oscA.frequency.value.toFixed(1) : null,
      engineGain: audio.engineGain ? +audio.engineGain.gain.value.toFixed(3) : null,
      raspGain: audio.raspGain ? +audio.raspGain.gain.value.toFixed(3) : null
    }
  };
});

await page.screenshot({ path: '/tmp/opencode/shots/race-final.jpg', type: 'jpeg', quality: 85 });
console.log(JSON.stringify({ info, errors }, null, 2));
await browser.close();

