import { createRequire } from 'node:module';
import { join } from 'node:path';
import { readFileSync } from 'node:fs';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const browser = await chromium.launch({
  headless: false, executablePath: '/opt/google/chrome/chrome',
  args: ['--enable-gpu', '--ignore-gpu-blocklist', '--enable-unsafe-webgpu', '--use-angle=vulkan',
    '--enable-features=Vulkan', '--use-vulkan=swiftshader', '--use-webgpu-adapter=swiftshader', '--disable-vulkan-surface']
});
const page = await browser.newPage({ viewport: { width: 1400, height: 1000 } });
await page.goto('http://localhost:3002/?demo=draw', { waitUntil: 'load' });
await page.waitForFunction(() => window.__apex && window.__apex.state === 'draw');
await page.waitForTimeout(600);

const labels = await page.evaluate(async () => {
  const { audio } = await import('/src/audio.js');
  const SR = 44100;
  const DUR = 8;
  const off = new OfflineAudioContext(2, SR * DUR, SR);
  audio.ctx = off;
  audio.master = off.createGain();
  audio.master.gain.value = 0.55;
  const comp = off.createDynamicsCompressor();
  comp.threshold.value = -14;
  comp.ratio.value = 4;
  audio.master.connect(comp);
  comp.connect(off.destination);
  audio.running = false;
  audio.startRace();

  const phase = (t) => {
    if (t < 0.7) return { speed: 0, throttle: 0, brake: 0, slip: 0, offroad: false };
    if (t < 5.2) {
      const k = (t - 0.7) / 4.5;
      return { speed: 95 * Math.pow(k, 0.62), throttle: 1, brake: 0, slip: 0, offroad: false };
    }
    if (t < 6.4) return { speed: Math.max(24, 95 - (t - 5.2) * 53), throttle: 0, brake: 1, slip: 0.2, offroad: false };
    return { speed: 20 + (t - 6.4) * 38, throttle: 1, brake: 0, slip: 0, offroad: false };
  };

  const marks = [];
  const fps = 30;
  for (let i = 1; i < DUR * fps; i++) {
    const when = i / fps;
    off.suspend(when).then(() => {
      const p = phase(when);
      audio.update(p);
      marks.push({ t: when, kmh: p.speed * 3.6, f: audio.oscA.frequency.value });
      off.resume();
    });
  }

  const buffer = await off.startRendering();
  audio.stopRace();
  const left = buffer.getChannelData(0);

  // ── radix-2 FFT ──────────────────────────────────────────────────
  const fft = (re, im) => {
    const n = re.length;
    for (let i = 1, j = 0; i < n; i++) {
      let bit = n >> 1;
      for (; j & bit; bit >>= 1) j ^= bit;
      j ^= bit;
      if (i < j) { [re[i], re[j]] = [re[j], re[i]]; [im[i], im[j]] = [im[j], im[i]]; }
    }
    for (let len = 2; len <= n; len <<= 1) {
      const ang = (-2 * Math.PI) / len;
      const wRe = Math.cos(ang), wIm = Math.sin(ang);
      for (let i = 0; i < n; i += len) {
        let curRe = 1, curIm = 0;
        for (let k = 0; k < len / 2; k++) {
          const uRe = re[i + k], uIm = im[i + k];
          const vRe = re[i + k + len / 2] * curRe - im[i + k + len / 2] * curIm;
          const vIm = re[i + k + len / 2] * curIm + im[i + k + len / 2] * curRe;
          re[i + k] = uRe + vRe; im[i + k] = uIm + vIm;
          re[i + k + len / 2] = uRe - vRe; im[i + k + len / 2] = uIm - vIm;
          const nextRe = curRe * wRe - curIm * wIm;
          curIm = curRe * wIm + curIm * wRe;
          curRe = nextRe;
        }
      }
    }
  };

  const N = 2048;
  const hop = 441; // 10 ms
  const cols = Math.floor((left.length - N) / hop);
  const bins = N / 2;
  const maxHz = 8000;
  const maxBin = Math.min(bins, Math.floor((maxHz / SR) * N));
  const canvas = document.createElement('canvas');
  canvas.width = cols;
  canvas.height = maxBin;
  canvas.id = 'spec';
  canvas.style.cssText = `position:fixed;left:0;top:0;z-index:99999;width:${cols}px;height:${maxBin * 2}px;image-rendering:pixelated;background:#000`;
  document.body.appendChild(canvas);
  const ctx2d = canvas.getContext('2d');
  const img = ctx2d.createImageData(cols, maxBin);
  const win = new Float32Array(N);
  for (let i = 0; i < N; i++) win[i] = 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (N - 1));

  for (let c = 0; c < cols; c++) {
    const re = new Float32Array(N);
    const im = new Float32Array(N);
    const start = c * hop;
    for (let i = 0; i < N; i++) re[i] = left[start + i] * win[i];
    fft(re, im);
    for (let b = 0; b < maxBin; b++) {
      const mag = Math.hypot(re[b], im[b]) / (N / 4);
      const db = 20 * Math.log10(mag + 1e-7);
      const v = Math.max(0, Math.min(1, (db + 80) / 72));
      const y = maxBin - 1 - b;
      const idx = (y * cols + c) * 4;
      // Ink/ember palette: quiet is deep navy, loud is white-hot orange.
      img.data[idx] = Math.round(255 * Math.min(1, v * 1.5));
      img.data[idx + 1] = Math.round(255 * Math.max(0, v * v * 1.05));
      img.data[idx + 2] = Math.round(255 * Math.max(0, 0.22 * v));
      img.data[idx + 3] = 255;
    }
  }
  ctx2d.putImageData(img, 0, 0);

  // Axis labels overlay in the page, screenshotted separately.
  const info = document.createElement('div');
  info.id = 'spec-info';
  info.style.cssText = 'position:fixed;left:0;top:520px;z-index:99999;color:#f3efe5;font:14px monospace;background:#070a0e;padding:14px;width:1000px;line-height:1.7';
  info.innerHTML = 'ENGINE SPECTROGRAM · 0-8 kHz · 8 s<br>' +
    'Frequency ladders = firing harmonics. Ramps = gears, drops = upshifts.<br>' +
    'Trace: ' + marks.filter((m, i) => i % 20 === 0).map((m) => `${m.t.toFixed(1)}s ${m.kmh.toFixed(0)}km/h ${m.f.toFixed(0)}Hz`).join(' · ');
  document.body.appendChild(info);
  return 'ok';
});

console.log(labels);
