await spec.screenshot({ path: '/tmp/opencode/shots/spectrogram.jpg', type: 'jpeg', quality: 92 });
const info = await page.$('#spec-info');
await info.screenshot({ path: '/tmp/opencode/shots/spectrogram-info.jpg', type: 'jpeg', quality: 92 });
await browser.close();
